<?phpnamespace ADMIN\AdminBundle\Entity;use Doctrine\ORM\Mapping as ORM;/** * ConsultaPersonaObservada * * @ORM\Entity * @ORM\Table("AUDITORIAPEROBS") */class AuditoriaPerObs{    /**     * @var integer     *     * @ORM\Column(name="id", type="integer")     * @ORM\Id     * @ORM\GeneratedValue(strategy="SEQUENCE")     * @ORM\SequenceGenerator(sequenceName="AUDITORIAPEROBS_ID_SEQ", allocationSize=1, initialValue=1)     */    private $id;        /**     * Many AuditoriaConsultaPerObs has One ConsultaPersonaObservada     *     * @ORM\ManyToOne(targetEntity="\ADMIN\AdminBundle\Entity\PersonaObservada"))     * @ORM\JoinColumn(name="PERSONAOBSERVADAID", referencedColumnName="PERSONAOBSID", nullable=false)     **/    private $personaObservada;        /**     * @var string     *     * @ORM\Column(name="ACCION", type="string", length=4000)     */    private $accion;        /**     * Many PersonaObservada has One Usuario     *     * @ORM\ManyToOne(targetEntity="\SEGURIDAD\SeguridadBundle\Entity\Usuario"))     * @ORM\JoinColumn(name="USUALTAID", referencedColumnName="USUARIOID", nullable=false)     **/    private $usuAlta;        /**     * @var \DateTime     *     * @ORM\Column(name="FECALTA", type="datetime", nullable=true)     */    private $fecAlta;            /**     * Get id     *     * @return integer     */    public function getId()    {        return $this->id;    }        /**     * Set accion     *     * @param string $accion     * @return AuditoriaPerObs     */    public function setAccion($accion)    {        $this->accion = $accion;                return $this;    }        /**     * Get accion     *     * @return string     */    public function getAccion()    {        return $this->accion;    }        /**     * Set fecAlta     *     * @param \DateTime $fecAlta     * @return AuditoriaPerObs     */    public function setFecAlta($fecAlta)    {        $this->fecAlta = $fecAlta;                return $this;    }        /**     * Get fecAlta     *     * @return \DateTime     */    public function getFecAlta()    {        return $this->fecAlta;    }            /**     * @return \ADMIN\AdminBundle\Entity\PersonaObservada     */    public function getPersonaObservada()    {        return $this->personaObservada;    }        /**     * @param \ADMIN\AdminBundle\Entity\PersonaObservada $personaObservada     * @return AuditoriaPerObs     */    public function setPersonaObservada($personaObservada)    {        $this->personaObservada = $personaObservada;                return $this;    }        /**     * Set usualta     *     * @param \SEGURIDAD\SeguridadBundle\Entity\Usuario $usuario     * @return AuditoriaPerObs     */    public function setUsuAlta(\SEGURIDAD\SeguridadBundle\Entity\Usuario $usuario)    {        $this->usuAlta = $usuario;                return $this;    }        /**     * Get usualta     *     * @return \SEGURIDAD\SeguridadBundle\Entity\Usuario     */    public function getUsuAlta()    {        return $this->usuAlta;    }    }